// Nova's run for one ticket and the line of VM slots, cut down to what this lab needs.
import {
  CancellationScope, condition, continueAsNew, defineQuery, defineSignal,
  getExternalWorkflowHandle, proxyActivities, setHandler, workflowInfo,
} from '@temporalio/workflow';

const act = proxyActivities({ startToCloseTimeout: '7 days', heartbeatTimeout: '2 minutes' });

export const request = defineSignal('request');
export const release = defineSignal('release');
export const slotGranted = defineSignal('slotGranted');
export const decidePlan = defineSignal('decidePlan');
export const lineQuery = defineQuery('line');
export const statusQuery = defineQuery('status');

const SLOTS = { nova: 3 };

// One per agent, ID slots:<agent>. It never ends; it hands out slots in the order they were asked for.
export async function slots(agent, holders = [], waiting = []) {
  setHandler(request, (id) => void waiting.push(id));
  setHandler(release, (id) => { holders = holders.filter((h) => h !== id); });
  setHandler(lineQuery, () => ({ holders, waiting }));
  while (workflowInfo().historyLength < 5000) {
    await condition(() => waiting.length > 0 && holders.length < (SLOTS[agent] ?? 1));
    const holder = waiting.shift();
    holders.push(holder);
    await getExternalWorkflowHandle(holder).signal(slotGranted);
  }
  await continueAsNew(agent, holders, waiting);
}

// Build it: hold one of the agent's slots only while fn runs, and give it back on every path.
// 1. register a handler for slotGranted, 2. signal request to slots:<agent> with your workflow ID,
// 3. wait until granted, 4. run fn, 5. in finally, signal release (nonCancellable, like the VM release).
// For now it holds no slot at all, so every ticket gets a VM at once.
export const withSlot = async (agent, fn) => fn();

export async function ticketToPr(ticket) {
  let status = 'Checking';
  let decision;
  setHandler(statusQuery, () => status);
  setHandler(decidePlan, (d) => { decision = d; });

  const inSandbox = async (task, size, label) => {
    status = 'Waiting for a slot';
    return withSlot('nova', async () => {
      status = label;
      const vm = await act.acquireSandbox(ticket, size);
      try {
        return await act.workInSandbox(vm, task);
      } finally {
        await CancellationScope.nonCancellable(() => act.releaseSandbox(vm)); // no VM is ever left behind
      }
    });
  };

  await inSandbox(`plan ${ticket}`, 'lite', 'Planning');
  status = 'Awaiting approval';
  await condition(() => decision !== undefined, '3 days'); // no VM and no slot while a person thinks
  if (decision !== 'approve') return (status = 'Stopped');
  const pr = await inSandbox(`build ${ticket}`, 'full', 'Working');
  return (status = `PR open: ${pr}`);
}
