// Pretend sandbox activities: they print what a real VM would do, and "work" for a few seconds.
import { heartbeat, sleep } from '@temporalio/activity';

const seconds = Number(process.env.WORK_SECONDS ?? 20);
const now = () => new Date().toTimeString().slice(0, 8);
let next = 1;

export const acquireSandbox = async (ticket, size) => {
  const vm = { id: `i-0${String(next++).padStart(3, '0')}`, size, ticket };
  console.log(`${now()}  ${ticket}  claimed a ${size} VM ${vm.id}`);
  return vm;
};

export const workInSandbox = async (vm, task) => {
  console.log(`${now()}  ${vm.ticket}  ${task} on ${vm.id} ...`);
  for (let s = 0; s < seconds; s += 2) {
    heartbeat(); // tells Temporal this worker is still alive
    await sleep(2000);
  }
  return task.startsWith('build') ? 'draft PR #2512' : 'plan v1';
};

export const releaseSandbox = async (vm) => {
  console.log(`${now()}  ${vm.ticket}  released ${vm.id}`);
};
EOF

