export const withSlot = async (agent, fn) => {
  const line = getExternalWorkflowHandle(`slots:${agent}`);
  const me = workflowInfo().workflowId;
  let granted = false;
  setHandler(slotGranted, () => { granted = true; });
  await line.signal(request, me);
  await condition(() => granted);
  try {
    return await fn();
  } finally {
    await CancellationScope.nonCancellable(() => line.signal(release, me));
  }
};
